files./work/flow.sh:
total=4; set -- -xy; getopts xy first
flow(){ local OPTIND=1; CDPATH=/search; pushd project >/work/sink; . /work/opts; getopts xy second; printf 'flow:%s|%s|%s|%s\n' "$total" "$sourced" "$second" "$PWD"; printf '<%s>\n' * | cat; popd >/work/sink; }
flow "$@"; getopts xy last; printf 'opts:%s|%s|%s\n' "$first" "$last" "$total"; cat; dirs -l -p
